def bipartite(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    colors = [-1] * (1 << n)
    colors[0] = 1

    for state in range(n - 1, -1, -1):
        if colors[state] == -1:
            Q = deque([state])
            while Q:
                current = Q.popleft()
                nodes = [node for node in graph[state] if colors[node] != -1]
                for node in nodes:
                    neighbors = [x for x in nodes if x != node]
                    newstate = state | (1 << node)
                    newcolor = (current ^ 1) if colors[newstate] == -1 else -1
                    colors[newstate] = newcolor
                    Q.extend(neighbors)

    for i in range(n):
        if colors[i] == -1:
            return "NO"
    return "YES"

