from bisect import bisect_left

def transform_permutation(perm):
    decomposition = [[perm[0]]]
    for current in perm[1:]:
        reachable = []
        for i in range(len(decomposition)):
            for k in range(len(decomposition[i])):
                if current == decomposition[i][k]:
                    break
                for j in range(len(decomposition[i])):
                    if current == decomposition[i][j] and i != j:
                        reachable.append((decomposition[i][k], decomposition[i][j]))
                        break
            if not reachable:
                decomposition.append([current])
                break
        l = bisect_left(perm, current)
        if l + 1 < len(perm):
            if reachable:
                decomposition[-1].extend(reachable)
                decomposition[-1].sort()
                decomposition[-1] = reachable + decomposition[-1][1:]
            else:
                decomposition[-1] = [current]
        for elem in decomposition[-1]:
            perm[l: l + 1] = [elem]
        decomposition.append([current])
        l = l + 1
    return ''.join(str(x) for x in perm)

