def preprocess_array(n, perm):
    preprocessed_array = [0] * n
    for i in range(n):
        preprocessed_array[(i + perm) % n] = perm + 1
    return preprocessed_array, sum(1 for x in perm if x != -1)

def increment_and_discard(old_len, changes, new_amount):
    if new_amount > changes:
        return old_len + new_amount - changes
    return old_len + changes if new_amount == changes else old_len

def process_queries(n, queries_type):
    changes = [0]
    preprocessed_array = []
    number_of_inversions = []
    last_permutation_removed_state = -1
    for query in queries_type:
        if query == 1:
            l, r = query
            changes.append(r - l + 1)
            preprocessed_array += [0] * (r - l + 1)
        elif query[0] == 2:
            l, r = query[1:]
            for i in range(l - 1, r - 1):
                if preprocessed_array[i] != -1:
                    current_sum = preprocessed_array[l-1] - preprocessed_array[i]
                    preprocessed_array[i] = preprocessed_array[r]
                    preprocessed_array[i + 1:] = [
                        increment_and_discard(current_sum, changes[-1], preprocessed_array[i + 1] - current_sum)
                        for j in range(1, len(preprocessed_array) - i - 1)
                    ]
                    preprocessed_array[r - 1] = -1  # Update to prevent further modifications
            q = preprocessed_array[:l-1] + [0] + [-1 for _ in range(l-1, min(len(preprocessed_array), r+1))]
            number_of_inversions.append(sum(q[x + 1] - q[x] for x in range(r - l + 1) if x != 0))
        elif query[0] == 1:
            l, r = query[1:]
            last_permutation_removed_state = (l - 1 + preprocessed_array[l-1]) % n
            preprocessed_array = [preprocessed_array[(i + last_permutation_removed_state) % n] if i < len(preprocessed_array) else -1 for i in range(max(0, l-1), max(r, len(preprocessed_array)))]
            preprocessed_array[:l-1] = [x + last_permutation_removed_state - (x < l-1) for x in range(max(0, l-1), max(r, len(preprocessed_array)))]
    return preprocessed_array, number_of_inversions

