from collections import defaultdict

def find_occurrences(s, t, k):
    n = len(s) - len(t) + 1
    count = 0
    t_dict = defaultdict(int)

    for i in range(n):
        for shift in range(-k, k + 1):
            char_diff = ord(s[i + len(t) + shift]) - ord(t[0])
            if abs(char_diff) <= k:
                t_dict[t[0]] += 1
                if len(t) == 1:
                    break
        if len(t) == 1:
            break

    for j in range(len(t)):
        t_dict[t[j]] -= 1
        if t_dict[t[j]] == 0:
            t_dict.pop(t[j])
        if len(t_dict) == 0:
            count += 1

    for i in range(1, n):
        t_dict.clear()
        for shift in range(-k, k + 1):
            if i + len(t) > n:
                break
            char_diff = ord(s[i + len(t) + shift]) - ord(t[0])
            if abs(char_diff) > k:
                continue
            t_dict[t[0]] += 1
            if j < len(t) - 1:
                if len(t[1:]) == 1:
                    break
                for t_shift in range(len(t) - 1):
                    for j_shift in range(-k, k + 1):
                        char_diff = ord(s[i + j_shift + len(t) + t_shift]) \
                                    - ord(t[j_shift + t[0]])
                        if abs(char_diff) <= k:
                            t_dict[t[j_shift + t[0]]] += 1
                            if len(t) == j:
                                break
                    if len(t) == j:
                        break
                j -= len(t) - 1
            # Check if we are doing backtracking correctly here yet, tedious.
            if len(t) == 1:
                break
        if len(t) == 1:
            break

    return count

