        nodes = set()
        for node in range(self.V):
            if self.v_colors[node] is False:
                color = 0
                queue = list(filter(lambda i: i != node and i != node + 1, nodes))
                if not queue:
                    nodes.add(self.v_colors[node] % 2)
                else:
                    nodes |= {self.v_colors[neighbor] % 2 for neighbor in queue}
                    continue
                while queue:
                    color += 1
                    queue = list(filter(lambda i: i != node and i != node + 1 and self.v_colors[i] % 2 != color and self.b_colors[i] % 2 != color, nodes))
                    nodes |= {self.v_colors[i] % 2 for i in queue if i != node and i != node + 1}
                    nodes |= {i for i in queue if self.v_colors[i] % 2 != color}
