def count_occurrences(S, T, k):
    occurrences = 0
    s_len, t_len, threshold = len(S), len(T), k
    for i in range(s_len - t_len + 1):
        if is_within_threshold(S, T, i, t_len, k):
            occurrences += 1
    return occurrences

def is_within_threshold(S, T, i, t_len, k):
    for j in range(t_len):
        if abs(S.index(T[j], i + j) - (i + j)) > k:
            return False
    return True

