class QueryManager:
    def __init__(self):
        self.a = []
        self.index = 1
        self.que = []
        self.last_ans = 0

    def input(self):
        self.n = int(input())
        a = list(map(int, input().split()))
        self.a = a
        self.que = []
        self.last_ans = 0
        return True

    def query_type_1(self, li, ri, ki):
        ans = []
        for i in range(ri):
            a = set(range(li, ri))
            a.update(self.a, *[k for k in range(1, self.n+1) if k not in a])
            ans.append(a[int(input())-1])
        return ans

    def query_type_2(self, li, ri, ki):
        self.index = (self.index + self.last_ans - 1) % self.n + 1
        self.que.append((li, ri, ki))
        li = ((li + self.last_ans - 1) % self.n + 1)
        ri = ((ri + self.last_ans - 1) % self.n + 1)
        ki = ((ki + self.last_ans - 1) % self.n + 1)
        if li > ri:
            li, ri = ri, li
        if li == ri:
            for i in range(self.n):
                if self.a[i] == ki:
                    self.last_ans += 1
            return 0
        if self.que[-1][0] <= li <= self.que[-1][1]:
            for i in range(li, ri+1):
                self.a[self.index-1] = self.a[i-1]
                self.index = 0 if self.index == self.n else self.index + 1
            self.que.pop()
        else:
            for i in range(li, ri+1):
                self.a[i-1] = self.a[self.index-1]
                if i == ri:
                    break
                else:
                    self.index = 1 if self.index == self.n else self.index + 1
        return self.first_0flag()

    def first_0flag(self):
        a = self.a
        n = len(a)
        for i in range(n-1, -1, -1):
            if a[i] == 0:
                return 1
        return 0


if __name__ == "__main__":
    q = QueryManager()
    q.input()
    while q.que:
        q.query_type_2(*q.que.pop())
