from collections import deque

def find_least_time(n, s, numbers):
    cost = [0] * n
    pos1, pos2 = 0, -1
    queue = deque([(0, False)])  # (index, clockwise)
    visited = [False] * n
    visited[s] = True
    robot_pos = 0

    while queue:
        i, clockwise = queue.popleft()

        if clockwize:
            move = 1 if numbers[i % n] > numbers[(i + 1) % n] else -1
        else:
            move = -1 if numbers[i % n] < numbers[(i + 1) % n] else 1
        time_cost = (i + move) % n
        cost[i] += (time_cost - i) + (numbers[time_cost % n] - numbers[i % n])

        if visited[time_cost] or (clockwise and time_cost == s or not clockwise and time_cost == n - s):
            continue

        visited[time_cost] = True

        if clockwise:
            queue.appendleft((time_cost, True))
        else:
            queue.append((time_cost, False))

    return cost.pop() + max(cost)

def simulate(numbers):
    n = len(numbers)
    res = deque()
    total_cost = find_least_time(n, 0, numbers)
    for i in range(n):
        if numbers[i] == total_cost:
            res.append(('+', i))
        elif numbers[i] > total_cost:
            res.append(('-', (i + 1) % n))
        else:
            res.append(('-', n - (i + 1) % n))

    return "\n".join(res.pop().split(" ") + list(map(str, [i for i in range(n) if numbers[i] < total_cost and numbers[i + i] >= total_cost]))) + "\n"

def main():
    n, s = map(int, input().split())
    numbers = list(map(int, input().split()))
    print(simulate(numbers))

main()
