                        global_approved.add((i, j))
                        seen.add((i, j))
                        override = global_overrides[prev_val]
                else:
                    override = None
            if _override:
                if (i, j) in global_approved:
                    global_approved.remove((i, j))
            if override is None:
                return global_seen_count
            seen.add((i, j))
            queue.append(((i, j), override, -1))
