def generate_strings(s, t):
    prefixes = set()
    for i in range(len(s) + 1):
        for j in range(len(t) + 1):
            prefix = s[:i] + t[:j]
            prefixes.add(prefix)
    return prefixes

def distinct_strings(s, t):
    s_prefixes = set()
    for i in range(1, len(s) + 1):
        s_prefixes.add(s[:i])

    t_prefixes = set()
    for i in range(1, len(t) + 1):
        t_prefixes.add(t[:i])

    distinct = set()
    for s_prefix in s_prefixes:
        for t_prefix in t_prefixes:
            distinct.add(s_prefix + t_prefix)
    return len(distinct)

