import math
from functools import lru_cache

def expected_guessments(n, T, p, t):
    @lru_cache(None)
    def dp(index, remaining_duration):
        if index == n or remaining_duration == 0:
            return 0
        if remaining_duration < t[index]:
            return 1
        return (dp(index + 1, remaining_duration) + p[index]) / 100
    return dp(0, T)

