from sortedcontainers import SortedList

def find_median(arr):
    if len(arr) % 2 == 0:
        return (arr[int((len(arr) + 1) / 2 - 1)] + arr[int(len(arr) / 2) - 1]) / 2
    else:
        return arr[int(len(arr) / 2) - 1]

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    al = SortedList()
    br = SortedList()

    for i in range(n):
        al.add(i * a[i])
        for j in range(i + 1, n):
            br.add(i * a[i] + (j - i) * a[j])

    medians = [al[i] + br[i] for i in range(len(al))]

    while True:
        median = find_median(medians)
        if len(al) == 1 or len(br) == 1:
            break
        if al[0] < br[-1]:
            br.add(median)
        else:
            al.add(median)

    return median

print(solve())
