    first_photos = []  # Potential highest photo for each player
    with_photos = []

    for i, (a1, b1, a2, b2) in enumerate(pairs):
        max_happiness['Alice'] += calculate_happiness_gain(a1, a2)
        max_happiness['Bonnie'] += calculate_happiness_gain(b1, b2)
        if a1 > b1 and not with_photos:
            heappush(with_photos, -a1)
            heappush(with_photos, -a2)
        elif b1 > a1 and not with_photos:
            heappush(with_photos, -b1)
            heappush(with_photos, -b2)
        elif a1 > b1 and with_photos:
            if -with_photos[0] >= a1:
                pair = (with_photos[0], -a2)
                heappop(with_photos)
                heappush(with_photos, pair)
        elif a1 < b1 and with_photos:
            if -with_photos[0] >= a2:
                pair = (with_photos[0], -b2)
                heappop(with_photos)
                heappush(with_photos, pair)

    for pair in with_photos:
        max_happiness['Alice'] += calculate_happiness_gain(pair[0], -pair[1])
        max_happiness['Bonnie'] += calculate_happiness_gain(-pair[0], pair[1])
        first_photos = list(item for item in first_photos if item[0] != pair[0])
        first_photos.append(pair)

    result = {}
    for key, value in max_happiness.items():
        if first_photos:
            left = calculate_happiness_gain(first_photos[0][0], value) if not second_photos else \
                calculate_happiness_gain(first_photos[0][0], -second_photos[0]) if second_photos else 0
        else:
            left = calculate_happiness_gain(a2 + b2, value)
        if not second_photos:
            right = calculate_happiness_gain(-first_photos[0][1], a1 + b1) if not first_photos else \
                calculate_happiness_gain(-first_photos[0][1], a2 + b2) if second_photos else -0
        else:
            right = calculate_happiness_gain(-first_photos[0][1], a1 + b1) if not first_photos else \
                calculate_happiness_gain(-first_photos[0][1], a2 + b2) if second_photos else 0
        result[key] = (left + right) // 2

