from collections import deque

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    pq = [(0, start)]
    visited = set()

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if neighbor not in visited and distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def find_shortest_path(graph, start, end):
    nonzero_distances = {node: distance for node, distance in graph.items() if distance != float('infinity') and node != end}
    nonzero_distances.update({end: 0})

    paths = [float('infinity') for _ in nonzero_distances] + [start]
    paths[0] = 0

    for _ in range(len(nonzero_distances) - 1):
        update = False
        for i in range(len(nonzero_distances)):
            node, distance = nonzero_distances.popitem()
            if paths[i] == distance:
                continue

            for neighbor, weight in graph.get(node, {}).items():
                new_distance = distance + weight

                if paths[i] > new_distance:
                    paths[i] = new_distance
                    nonzero_distances[neighbor] = new_distance
                    update = True

        if not update:
            return -1

    return paths[-1]

def solution(n, m, corridors):
    graph = {node: {} for node in range(1, n + 1)}
    for u, v in corridors:
        graph[u][v] = 1
        graph[v][u] = 1

    distances = dijkstra(graph, 1)
    optimal_path = [1]
    i = 0
    while distances[n] > optimal_path[-1] and i < len(distances):
        optimal_path.append(i + 1)
        distances[n] -= optimal_path[-1]
        i += 2

    if distances[n] == 0:
        return str(len(optimal_path) - 1)
    else:
        return "-1"

# Example usage
