import sys

def compute_recognition_rate(n, T, p, t):
    recognition_rates = []
    for pi, ti in zip(p, t):
        if pi == 100:
            recognition_rates.append(ti / t)
        elif pi == 50:
            recognition_rates.append(ti / 2 * t)
    return recognition_rates

def expected_recognized_songs(n, T, p, t):
    recognition_rates = compute_recognition_rate(n, T, p, t)
    total_seconds = T
    expected_recognized = 0

    for rate in recognition_rates:
        if rate <= 5:
            expected_recognized += 1
            total_seconds -= 1
        elif rate < 10:
            expected_recognized += 1 + rate / 10
            total_seconds -= rate / 10
        else:
            break
    return expected_recognized

