def count_occurrences(s, t, k):
    occurrences = 0
    n, m, K = len(s), len(t), k
    dp = [[0] * (n - m + 1) for _ in range(K + 1)]

    for i in range(n - m + 1):
        for j in range(K + 1):
            if s[i:i + m] == t[:m] and j <= K:
                dp[j][i] = j
                for k in range(j + 1, K + 1):
                    if i + m - dp[k - 1] <= n and dp[k][i + m - dp[k - 1]] >= j:
                        dp[k][i + m] = i + m - dp[k - 1]
                        occurrences += 1
                        break
                    if j == K:
                        dp[k][i + m] = n

    return occurrences

