def count_connect_components(n, m):
    """Count the number of connected components consisting of 1's in a binary matrix."""
    connections = 0
    matrix = []
    for _ in range(n):
        line = input().decode('hex')
        matrix.append([int(char) for char in line])
    for i in range(n):
        for j in range(m / 4):
            if matrix[i][j * 4 + 3] == 1:
                for k in range(3):
                    for l in range(3):
                        if matrix[i][j * 4 + k] == 1 and matrix[i][j * 4 + l] == 1:
                            connections += 1
                            for r in range(4):
                                matrix[i][j * 4 + k] = 0
                                matrix[i][j * 4 + l] = 0
                                matrix[i][j * 4 + k - r] = 0
                                matrix[i][j * 4 + l - r] = 0
    return connections

