from heapq import heappush, heappop

def maximize_happiness_difference(stacks):
    """
    Calculate the maximum difference in happiness between Alice and Bonnie
    given two photo stacks and both playing optimally.

    :param stacks: A list of tuples, where each tuple represents a photo stack.
    :return: The maximum happiness difference as an integer.
    """
    def max_difference(stacks):
        left, right = stacks[0][0], -stacks[0][1]
        for stack in stacks[1:]:
            if left <= stack[0]:
                left, right = stack[0], -stack[1]
            elif right >= stack[0]:
                left, right = stack[0], -stack[1]
        return max(right-left, 0)

    return max_difference(stacks)


