import heapq
from bisect import bisect_left

def find_median_of_heap(heap):
    if len(heap) % 2 == 0:
        return (heap[0] + heap[1]) // 2
    else:
        return heap[0]

def next_larger(array, n):
    stack = []
    next_larger_values = [-1] * n
    for i in range(n - 1, -1, -1):
        while stack and stack[-1] <= array[i]:
            stack.pop()
        if stack:
            next_larger_values[i] = stack[-1]
        stack.append(array[i])
    return next_larger_values

def find_greatest_divisor(sequence):
    n = len(sequence)
    heap = []
    next_larger = next_larger(sequence, n)
    for i in range(n):
        while heap and heap[0] <= next_larger[i]:
            heapq.heappop(heap)
        median = float('-inf')
        if heap:
            median = find_median_of_heap(heap)
        ans = median
        for d in range(sequence[i], sequence[i] + 100000 // 2):
            if next_larger[i] >= d:
                continue
            while heap and d > heap[0]:
                heapq.heappop(heap)
            if len(heap) == 0 or heap[0] < d:
                heapq.heappush(heap, d)
        max_xor_sequence = []
        current_xor = 0
        for d in sequence[i:]:
            current_xor ^= d
            max_xor_sequence.append(current_xor)
        while heap:
            current_xor ^= heap[0]
            max_xor_sequence.append(current_xor)
        for i in range(len(max_xor_sequence) - 1):
            xor_of_prev = (next_larger[max_xor_sequence[i]] if i else 0) ^ (max_xor_sequence[i + 1] if i + 1 < len(max_xor_sequence) else 0)
            if xor_of_prev >= ans:
                continue
            while len(heap) and d > heap[0]:
                heapq.heappop(heap)
            if d > xor_of_prev:
                break
            diff = heap[0] ^ xor_of_prev
            if diff > d:
                continue
