from collections import deque

def is_bipartite(graph):
    n = len(graph)
    color = [0] * n  # 0 for uncolored, 1 for color 1, 2 for color 2

    for i in range(n):
        if color[i] == 0:
            q = deque([i])
            color[i] = 1
            while q:
                curr = q.popleft()
                for neighbor in graph[curr]:
                    if color[neighbor] != 0:
                        if color[neighbor] != color[curr]:
                            return False
                        continue
                    color[neighbor] = -color[curr]
                    q.append(neighbor)
    return True

